1	// Regression coverage for audit pagination once a pinned range is already
2	// exhausted. An auditor obtains the organization's end sequence and
3	// fingerprint from AuditQuery and continues with AuditPage; the zero/terminal
4	// cursor only says "no further records exist inside this fixed range", so it
5	// must never make a bad checkpoint pass as a successful empty query. These
6	// tests pin the contract of the existing AuditQuery/AuditPage entry points
7	// for calls made after the walk has ended:
8	//
9	//   - With the genuine checkpoint of the original query, both terminal
10	//     positions — the end cursor 0 and the one-past-the-pinned-end cursor
11	//     EndSeq+1 — succeed with an empty page, Next stays 0, and the
12	//     checkpoint's organization, end sequence and fingerprint come back
13	//     byte-for-byte. Records the organization produces afterwards never
14	//     enter the finished query, from either cursor, and the returned end
15	//     sequence is not advanced to the current chain tail.
16	//   - The EndSeq+1 cursor is an empty end page, not an out-of-range error
17	//     and not a restart that redelivers records from sequence 1.
18	//   - Even at a terminal cursor the checkpoint material is still verified:
19	//     a different fingerprint, or a changed end sequence paired with the
20	//     old position's fingerprint, fails with ErrInvalidRange exactly as it
21	//     does mid-paging and delivers no page.
22	//   - A genuine checkpoint below the current chain tail stays valid: a
23	//     historical end sequence with the fingerprint that really covered that
24	//     position pages its prefix and is never blanket-rejected or silently
25	//     re-stamped with the current tail fingerprint.
26	//   - An organization with no records is not exempt: the root checkpoint
27	//     plus cursor 0 yields an empty page only while its genesis fingerprint
28	//     matches; a wrong root fingerprint is rejected. A legitimate empty
29	//     page (page with nil error) is therefore distinct from a checkpoint
30	//     error (nil page with ErrInvalidRange) — zero records alone never
31	//     marks the call successful.
32	//
33	// Every call here is read-only: no audit record is appended, no policy
34	// version changes, and ordinary continued paging keeps its filters and
35	// ascending record order.
36	package darksafe
37	
38	import (
39		"errors"
40		"reflect"
41		"testing"
42	)
43	
44	// exhaustedRangeFixture builds an organization interleaving a policy change
45	// and access decisions:
46	//
47	//	seq 1  publish v1 (allow u1 read org/a)
48	//	seq 2  u1 read -> allow (v1)
49	//	seq 3  u2 read -> no-match denial
50	//
51	// It pages an unfiltered query (page size 2) to genuine exhaustion and
52	// returns the store together with the final empty page, whose checkpoint
53	// pins end sequence 3.
54	func exhaustedRangeFixture(t *testing.T) (*Store, *AuditPage) {
55		t.Helper()
56		s := NewStore()
57		if _, err := s.Publish("acme", 0, []Policy{
58			allowPolicy("p-allow", "u1", "read", "org/a", false),
59			{ID: "p-deny", Subject: "u2", Action: "write", Scope: "org/a", Effect: EffectDeny},
60		}); err != nil {
61			t.Fatal(err)
62		}
63		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq 2, allow
64		s.Decide("acme", request("acme", "u2", "r1", "org/a", "read")) // seq 3, no-match denial
65	
66		first, err := s.AuditQuery("acme", 1, 2, "", "")
67		if err != nil {
68			t.Fatal(err)
69		}
70		if got := recordSeqs(first.Records); !reflect.DeepEqual(got, []int{1, 2}) || first.Next != 3 {
71			t.Fatalf("first page = %+v, want seqs [1 2], next 3", first)
72		}
73		last, err := s.AuditPage(first.Checkpoint, first.Next, 2, "", "")
74		if err != nil {
75			t.Fatal(err)
76		}
77		if got := recordSeqs(last.Records); !reflect.DeepEqual(got, []int{3}) || last.Next != 0 {
78			t.Fatalf("final page = %+v, want seq [3], next 0", last)
79		}
80		return s, last
81	}
82	
83	// requireEmptyTerminalPage fails unless the page is a successful empty end
84	// page (nil error, no records, Next 0) carrying the submitted checkpoint
85	// unchanged. A zero-length record list paired with an error would not
86	// satisfy this: the caller must distinguish a valid empty page from a
87	// rejected checkpoint.
88	func requireEmptyTerminalPage(t *testing.T, page *AuditPage, err error, cp Checkpoint, beginSeq int) {
89		t.Helper()
90		if err != nil {
91			t.Fatalf("terminal page err = %v, want nil", err)
92		}
93		if page == nil {
94			t.Fatal("terminal page is nil with nil error")
95		}
96		if len(page.Records) != 0 {
97			t.Fatalf("terminal page delivered %d records %v, want none", len(page.Records), recordSeqs(page.Records))
98		}
99		if page.Next != 0 {
100			t.Fatalf("terminal page next = %d, want 0", page.Next)
101		}
102		if page.BeginSeq != beginSeq {
103			t.Fatalf("terminal page begin = %d, want %d", page.BeginSeq, beginSeq)
104		}
105		if page.EndSeq != cp.EndSeq {
106			t.Fatalf("terminal page end = %d, want pinned %d", page.EndSeq, cp.EndSeq)
107		}
108		if page.Org != cp.Org {
109			t.Fatalf("terminal page org = %q, want %q", page.Org, cp.Org)
110		}
111		if page.Checkpoint != cp {
112			t.Fatalf("terminal page checkpoint = %+v, want original %+v", page.Checkpoint, cp)
113		}
114	}
115	
116	// TestAuditPageAfterExhaustionKeepsRangeClosed pins that calling AuditPage
117	// after pagination ended — at cursor 0 and at EndSeq+1 — re-verifies the
118	// checkpoint and answers with an empty, still-closed page. New decisions
119	// produced afterwards do not reopen the finished query or advance its end
120	// sequence toward the current chain tail.
121	func TestAuditPageAfterExhaustionKeepsRangeClosed(t *testing.T) {
122		s, last := exhaustedRangeFixture(t)
123		cp := last.Checkpoint
124		if cp.EndSeq != 3 || cp.Org != "acme" || cp.Fingerprint == "" {
125			t.Fatalf("pinned checkpoint = %+v, want acme ending at 3 with a fingerprint", cp)
126		}
127	
128		// Cursor 0 on the already finished walk: empty page, the walk stays
129		// finished, and org/end/fingerprint come back exactly as pinned.
130		again, err := s.AuditPage(cp, 0, 2, "", "")
131		requireEmptyTerminalPage(t, again, err, cp, 1)
132	
133		// Cursor EndSeq+1 is the other legal end position: an empty end page,
134		// not ErrInvalidRange, and not a restart redelivering seq 1..3.
135		onePast, err := s.AuditPage(cp, cp.EndSeq+1, 2, "", "")
136		requireEmptyTerminalPage(t, onePast, err, cp, cp.EndSeq+1)
137	
138		// The organization produces a new decision after the query ended.
139		s.Decide("acme", request("acme", "u9", "r1", "org/a", "read")) // seq 4
140		fresh, err := s.AuditQuery("acme", 1, 10, "", "")
141		if err != nil {
142			t.Fatal(err)
143		}
144		if fresh.Checkpoint.EndSeq != 4 || len(fresh.Records) != 4 {
145			t.Fatalf("fresh query = %+v, want 4 records ending at 4", fresh)
146		}
147	
148		// Neither terminal position lets the new record into the finished query
149		// or advances the returned end sequence/fingerprint to the current tail.
150		for _, cursor := range []int{0, cp.EndSeq + 1} {
151			page, err := s.AuditPage(cp, cursor, 10, "", "")
152			requireEmptyTerminalPage(t, page, err, cp, func() int {
153				if cursor == 0 {
154					return 1
155				}
156				return cursor
157			}())
158			if page.Checkpoint.EndSeq == fresh.Checkpoint.EndSeq ||
159				page.Checkpoint.Fingerprint == fresh.Checkpoint.Fingerprint {
160				t.Fatalf("finished query advanced to the current tail: %+v vs fresh %+v",
161					page.Checkpoint, fresh.Checkpoint)
162			}
163		}
164	
165		// Normal continued paging over the FINISHED range keeps its filter and
166		// ascending order: the decision-only view skips the seq-1 policy change
167		// and ends at seq 3 — seq 4, a decision appended after the pin, never
168		// leaks in even though it would match the filter in a fresh query.
169		d1, err := s.AuditPage(cp, 1, 1, AuditDecision, "")
170		if err != nil {
171			t.Fatal(err)
172		}
173		if got := recordSeqs(d1.Records); !reflect.DeepEqual(got, []int{2}) || d1.Next != 3 {
174			t.Fatalf("filtered continuation page 1 = %+v, want seq [2], next 3", d1)
175		}
176		if d1.Checkpoint != cp {
177			t.Fatalf("filtered continuation drifted checkpoint: %+v vs %+v", d1.Checkpoint, cp)
178		}
179		d2, err := s.AuditPage(cp, d1.Next, 1, AuditDecision, "")
180		if err != nil {
181			t.Fatal(err)
182		}
183		if got := recordSeqs(d2.Records); !reflect.DeepEqual(got, []int{3}) || d2.Next != 0 {
184			t.Fatalf("filtered continuation page 2 = %+v, want seq [3], next 0; appended seq 4 leaked", d2)
185		}
186		closed, err := s.AuditPage(cp, 0, 1, AuditDecision, "")
187		requireEmptyTerminalPage(t, closed, err, cp, 1)
188	
189		// All terminal and continuation calls were read-only: the appended
190		// decision is the only record added by this test, and the policy
191		// version never moved.
192		if got := recordSeqs(drainAudit(t, s, "acme", "", "")); !reflect.DeepEqual(got, []int{1, 2, 3, 4}) {
193			t.Fatalf("chain after terminal calls = %v, want [1 2 3 4]", got)
194		}
195		if v := s.CurrentVersion("acme"); v != 1 {
196			t.Fatalf("version = %d, want 1; terminal paging must not republish", v)
197		}
198		// The genuine checkpoint still pages normally after every closed call.
199		more, err := s.AuditPage(cp, 1, 10, "", "")
200		if err != nil {
201			t.Fatalf("genuine checkpoint no longer pages: %v", err)
202		}
203		if got := recordSeqs(more.Records); !reflect.DeepEqual(got, []int{1, 2, 3}) {
204			t.Fatalf("genuine continuation = %v, want [1 2 3]", got)
205		}
206	}
207	
208	// TestAuditPageAtTerminalCursorsRejectsTamperedCheckpoint pins that an end
209	// marker never excuses a material mismatch: a wrong fingerprint, or an end
210	// sequence changed while the old position's fingerprint is kept, fails with
211	// ErrInvalidRange at cursor 0 and at EndSeq+1 exactly as it does on an
212	// ordinary mid-paging cursor, and no page is delivered.
213	func TestAuditPageAtTerminalCursorsRejectsTamperedCheckpoint(t *testing.T) {
214		s, last := exhaustedRangeFixture(t)
215		cp := last.Checkpoint
216	
217		terminalCursors := []int{0, cp.EndSeq + 1}
218	
219		// Different fingerprint on an otherwise intact checkpoint.
220		wrongFP := cp
221		wrongFP.Fingerprint = "00"
222		for _, cursor := range terminalCursors {
223			page, err := s.AuditPage(wrongFP, cursor, 2, "", "")
224			if !errors.Is(err, ErrInvalidRange) {
225				t.Fatalf("wrong fingerprint at terminal cursor %d: err = %v, want ErrInvalidRange", cursor, err)
226			}
227			if page != nil {
228				t.Fatalf("wrong fingerprint at terminal cursor %d delivered page %+v", cursor, page)
229			}
230		}
231	
232		// Change only the end sequence while keeping the fingerprint that
233		// covered the old position (seq 3); it matches no position under the
234		// claimed end (seq 2).
235		shifted := cp
236		shifted.EndSeq = 2
237		for _, cursor := range terminalCursors {
238			page, err := s.AuditPage(shifted, cursor, 2, "", "")
239			if !errors.Is(err, ErrInvalidRange) {
240				t.Fatalf("shifted end at terminal cursor %d: err = %v, want ErrInvalidRange", cursor, err)
241			}
242			if page != nil {
243				t.Fatalf("shifted end at terminal cursor %d delivered page %+v", cursor, page)
244			}
245		}
246	
247		// Re-binding the same material to another organization name fails too:
248		// the fingerprint binds the organization.
249		foreign := cp
250		foreign.Org = "globex"
251		for _, cursor := range terminalCursors {
252			page, err := s.AuditPage(foreign, cursor, 2, "", "")
253			if !errors.Is(err, ErrInvalidRange) {
254				t.Fatalf("foreign org at terminal cursor %d: err = %v, want ErrInvalidRange", cursor, err)
255			}
256			if page != nil {
257				t.Fatalf("foreign org at terminal cursor %d delivered page %+v", cursor, page)
258			}
259		}
260	
261		// The error category is the same one ordinary paging produces, on a
262		// live cursor — terminals are not a softer validation path.
263		for _, bad := range []Checkpoint{wrongFP, shifted, foreign} {
264			if _, err := s.AuditPage(bad, 1, 2, "", ""); !errors.Is(err, ErrInvalidRange) {
265				t.Fatalf("mid-paging with %+v: err = %v, want ErrInvalidRange", bad, err)
266			}
267		}
268	
269		// The genuine checkpoint is unaffected by the rejected attempts.
270		if _, err := s.AuditPage(cp, 0, 2, "", ""); err != nil {
271			t.Fatalf("genuine checkpoint rejected after tampered calls: %v", err)
272		}
273		if got := len(drainAudit(t, s, "acme", "", "")); got != 3 {
274			t.Fatalf("records = %d, want 3; rejected paging must not append", got)
275		}
276	}
277	
278	// TestAuditPageHistoricalCheckpointBelowTailStaysValid pins the distinction
279	// between a corrupted checkpoint and an old-but-genuine one: when the chain
280	// tail has advanced, a checkpoint whose end sequence is below the tail is
281	// still valid if its fingerprint really covered that historical position.
282	// It pages only its own prefix, is never re-stamped with the current tail
283	// fingerprint, and tampering with it is rejected even at the end cursors.
284	func TestAuditPageHistoricalCheckpointBelowTailStaysValid(t *testing.T) {
285		s := NewStore()
286		if _, err := s.Publish("acme", 0, []Policy{
287			allowPolicy("p1", "u1", "read", "org/a", false),
288		}); err != nil {
289			t.Fatal(err)
290		}
291		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq 2
292	
293		// The caller saved this checkpoint when seq 2 was the tail.
294		oldRecs, oldCP, err := s.AuditExport("acme", 2)
295		if err != nil {
296			t.Fatal(err)
297		}
298		if oldCP.EndSeq != 2 || len(oldRecs) != 2 {
299			t.Fatalf("historical export = %+v, want 2 records ending at 2", oldCP)
300		}
301	
302		// The chain grows afterwards: a new publish and a new decision.
303		if _, err := s.Publish("acme", 1, nil); err != nil { // seq 3, v2 empty
304			t.Fatal(err)
305		}
306		s.Decide("acme", request("acme", "u2", "r1", "org/a", "read")) // seq 4
307		_, tailCP, err := s.AuditExport("acme", 0)
308		if err != nil {
309			t.Fatal(err)
310		}
311		if tailCP.EndSeq != 4 || tailCP.Fingerprint == oldCP.Fingerprint {
312			t.Fatalf("tail checkpoint = %+v, want end 4 with a fingerprint distinct from seq 2", tailCP)
313		}
314	
315		// Cursor 0 against the old range: empty success, range still ends at 2,
316		// fingerprint preserved rather than replaced by the current tail's.
317		closed, err := s.AuditPage(oldCP, 0, 10, "", "")
318		requireEmptyTerminalPage(t, closed, err, oldCP, 1)
319	
320		// EndSeq+1 is an empty end page even though seq 3 now exists right
321		// behind it: no false out-of-range, no restart delivering seq 1..2.
322		onePast, err := s.AuditPage(oldCP, oldCP.EndSeq+1, 10, "", "")
323		requireEmptyTerminalPage(t, onePast, err, oldCP, oldCP.EndSeq+1)
324	
325		// Ordinary continuation over the historical prefix yields exactly seq
326		// 1..2 in ascending order and never reads the appended tail.
327		page, err := s.AuditPage(oldCP, 1, 1, "", "")
328		if err != nil {
329			t.Fatalf("historical prefix paging: %v", err)
330		}
331		if got := recordSeqs(page.Records); !reflect.DeepEqual(got, []int{1}) || page.Next != 2 {
332			t.Fatalf("historical page 1 = %+v, want seq [1], next 2", page)
333		}
334		page, err = s.AuditPage(oldCP, page.Next, 1, "", "")
335		if err != nil {
336			t.Fatal(err)
337		}
338		if got := recordSeqs(page.Records); !reflect.DeepEqual(got, []int{2}) || page.Next != 0 {
339			t.Fatalf("historical page 2 = %+v, want seq [2], next 0", page)
340		}
341	
342		// An old checkpoint is not blanket-accepted: its material must match
343		// that old position. Wrong fingerprint at either terminal cursor fails.
344		tampered := oldCP
345		tampered.Fingerprint = tailCP.Fingerprint // genuine value, wrong position
346		for _, cursor := range []int{0, oldCP.EndSeq + 1} {
347			p, err := s.AuditPage(tampered, cursor, 10, "", "")
348			if !errors.Is(err, ErrInvalidRange) {
349				t.Fatalf("historical checkpoint with tail fingerprint at cursor %d: err = %v, want ErrInvalidRange", cursor, err)
350			}
351			if p != nil {
352				t.Fatalf("tampered historical checkpoint delivered page %+v", p)
353			}
354		}
355		// Keeping the old fingerprint while claiming the new tail is equally bad.
356		relabeled := oldCP
357		relabeled.EndSeq = tailCP.EndSeq
358		if _, err := s.AuditPage(relabeled, 0, 10, "", ""); !errors.Is(err, ErrInvalidRange) {
359			t.Fatalf("old fingerprint under new end: err = %v, want ErrInvalidRange", err)
360		}
361	
362		// Reading historical pages changed nothing.
363		if got := recordSeqs(drainAudit(t, s, "acme", "", "")); !reflect.DeepEqual(got, []int{1, 2, 3, 4}) {
364			t.Fatalf("chain changed while reading historical checkpoint: %v", got)
365		}
366		if v := s.CurrentVersion("acme"); v != 2 {
367			t.Fatalf("version = %d, want 2; historical paging must not republish", v)
368		}
369	}
370	
371	// TestAuditPageEmptyOrgRootCheckpointStillVerifiesFingerprint pins that an
372	// organization with no records gets no exemption: the genuine root
373	// checkpoint (end 0, genesis fingerprint) plus cursor 0 returns an empty
374	// page, but a wrong root fingerprint is rejected with ErrInvalidRange. The
375	// test distinguishes the two outcomes by (page, err), not by record count:
376	// a rejected call also "returns no records".
377	func TestAuditPageEmptyOrgRootCheckpointStillVerifiesFingerprint(t *testing.T) {
378		s := NewStore()
379	
380		root, err := s.AuditQuery("blank", 1, 10, "", "")
381		if err != nil {
382			t.Fatal(err)
383		}
384		if root.Checkpoint != (Checkpoint{Org: "blank", EndSeq: 0, Fingerprint: genesisFingerprint("blank")}) {
385			t.Fatalf("empty-org checkpoint = %+v, want the genesis checkpoint", root.Checkpoint)
386		}
387		if len(root.Records) != 0 || root.Next != 0 {
388			t.Fatalf("empty-org first page = %+v, want empty with next 0", root)
389		}
390	
391		// Genuine root checkpoint replayed at the terminal cursor: valid empty page.
392		empty, err := s.AuditPage(root.Checkpoint, 0, 10, "", "")
393		requireEmptyTerminalPage(t, empty, err, root.Checkpoint, 1)
394	
395		// Same end sequence and cursor, wrong root fingerprint: rejected, and no
396		// page is delivered. The empty chain did not waive the fingerprint check.
397		badRoot := root.Checkpoint
398		badRoot.Fingerprint = "00"
399		page, err := s.AuditPage(badRoot, 0, 10, "", "")
400		if !errors.Is(err, ErrInvalidRange) {
401			t.Fatalf("wrong root fingerprint err = %v, want ErrInvalidRange", err)
402		}
403		if page != nil {
404			t.Fatalf("wrong root fingerprint delivered page %+v", page)
405		}
406		// And not only at cursor 0: a one-past-root cursor must not bypass it.
407		if page, err := s.AuditPage(badRoot, 1, 10, "", ""); !errors.Is(err, ErrInvalidRange) || page != nil {
408			t.Fatalf("wrong root fingerprint at cursor 1 = (%+v, %v), want nil page, ErrInvalidRange", page, err)
409		}
410	
411		// Nothing was created by the queries, successful or rejected.
412		if recs := drainAudit(t, s, "blank", "", ""); len(recs) != 0 {
413			t.Fatalf("empty org gained records: %+v", recs)
414		}
415		if v := s.CurrentVersion("blank"); v != 0 {
416			t.Fatalf("empty org version = %d, want 0", v)
417		}
418	
419		// A store that has never even seen the organization applies the same
420		// rule: a matching genesis root is a valid empty page, any other
421		// fingerprint is ErrInvalidRange.
422		fresh := NewStore()
423		neverSeen := Checkpoint{Org: "ghost", EndSeq: 0, Fingerprint: genesisFingerprint("ghost")}
424		ghostPage, err := fresh.AuditPage(neverSeen, 0, 10, "", "")
425		if err != nil {
426			t.Fatalf("unseen org with genesis checkpoint err = %v, want nil", err)
427		}
428		if ghostPage == nil || len(ghostPage.Records) != 0 || ghostPage.Next != 0 ||
429			ghostPage.Checkpoint != neverSeen {
430			t.Fatalf("unseen org genesis page = %+v, want empty page preserving the root checkpoint", ghostPage)
431		}
432		badGhost := neverSeen
433		badGhost.Fingerprint = genesisFingerprint("someone-else")
434		if p, err := fresh.AuditPage(badGhost, 0, 10, "", ""); !errors.Is(err, ErrInvalidRange) || p != nil {
435			t.Fatalf("unseen org with foreign root fingerprint = (%+v, %v), want nil page, ErrInvalidRange", p, err)
436		}
437	}
