	fmt.Printf("page %d (pinned range %d-%d, checkpoint end=%d fingerprint=%s):\n",
		no, page.BeginSeq, page.EndSeq, page.Checkpoint.EndSeq, page.Checkpoint.Fingerprint)
	if len(page.Records) == 0 {
		fmt.Println("  (no matching records)")
	}
