1	// Checkpoint-file reading for `darksafe review --checkpoint FILE`. The
2	// separately retained checkpoint is the same small plain-text document the
3	// offline_review example writes: one key=value item per line, three keys
4	// (org, end_seq, fingerprint) each exactly once, in any order, with one
5	// optional trailing newline.
6	//
7	// Byte fidelity matters most: the org line uses Go-style double quoting
8	// (the same spelling fmt.Sprintf("org=%q", ...) emits), and reading it
9	// back must restore the organization's ORIGINAL bytes — Chinese, leading
10	// and trailing spaces, escaped control characters and non-UTF-8 bytes
11	// (0xff and 0xfe written as \xff/\xfe, never folded onto U+FFFD).
12	//
13	// Every shape deviation is an invocation error the review command reports
14	// with exit code 2: the file cannot be read, a field is missing or
15	// repeated, an unknown key or non-empty stray line appears, the quoted
16	// organization is empty or mis-escaped, the end sequence is not a
17	// non-negative decimal integer the process's int type can represent, or
18	// the fingerprint is not 64 hexadecimal characters.
19	package main
20	
21	import (
22		"bytes"
23		"fmt"
24		"os"
25		"strconv"
26		"unicode/utf8"
27	
28		"github.com/asdhoaiqqq/darksafe-access/darksafe"
29	)
30	
31	// readCheckpointFile reads and strictly parses one independently saved
32	// checkpoint document. A read failure names the offending file; a shape
33	// failure names the file and the specific line/item at fault.
34	func readCheckpointFile(path string) (darksafe.Checkpoint, error) {
35		data, err := os.ReadFile(path)
36		if err != nil {
37			return darksafe.Checkpoint{}, fmt.Errorf("cannot read checkpoint %q: %v", path, err)
38		}
39		return parseCheckpointDocument(path, data)
40	}
41	
42	// parseCheckpointDocument validates the document shape and decodes the
43	// three items. Splitting on '\n' means no item value can smuggle a newline
44	// across a line boundary; the single trailing newline the format allows is
45	// consumed by trimming exactly one '\n' from the tail — a second trailing
46	// newline becomes an empty line and fails like any other extra line.
47	func parseCheckpointDocument(path string, data []byte) (darksafe.Checkpoint, error) {
48		if len(data) > 0 && data[len(data)-1] == '\n' {
49			data = data[:len(data)-1]
50		}
51	
52		var cp darksafe.Checkpoint
53		var seenOrg, seenEndSeq, seenFingerprint bool
54		for lineNo, rawLine := range bytes.Split(data, []byte{'\n'}) {
55			lineNo := lineNo + 1
56			eq := bytes.IndexByte(rawLine, '=')
57			if eq <= 0 {
58				// eq < 0: no '=' on the line; eq == 0: an empty key. Both are
59				// non-empty miscellany (a wholly empty line too: the format's
60				// only permitted emptiness is the one trailing newline already
61				// trimmed above).
62				return darksafe.Checkpoint{}, fmt.Errorf(
63					"checkpoint %q line %d: expected one of org=..., end_seq=..., fingerprint=..., got %q",
64					path, lineNo, rawLine)
65			}
66			key := string(rawLine[:eq])
67			value := rawLine[eq+1:]
68	
69			switch key {
70			case "org":
71				if seenOrg {
72					return darksafe.Checkpoint{}, fmt.Errorf(
73						"checkpoint %q line %d: duplicate field org", path, lineNo)
74				}
75				seenOrg = true
76				org, err := parseCheckpointOrg(path, lineNo, value)
77				if err != nil {
78					return darksafe.Checkpoint{}, err
79				}
80				cp.Org = org
81			case "end_seq":
82				if seenEndSeq {
83					return darksafe.Checkpoint{}, fmt.Errorf(
84						"checkpoint %q line %d: duplicate field end_seq", path, lineNo)
