package darksafe

import (
	"errors"
	"testing"
)

func TestScratchEmptyCheckpoint(t *testing.T) {
	org := "blank"
	cp := Checkpoint{Org: org, EndSeq: 0, Fingerprint: genesisFingerprint(org)}

	// Case A: store has never visited the org.
	fresh := NewStore()
	pA0, errA0 := fresh.AuditPage(cp, 0, 10, "", "")
	t.Logf("FRESH cursor0: page=%+v err=%v", pA0, errA0)
	pA1, errA1 := fresh.AuditPage(cp, 1, 10, "", "")
	t.Logf("FRESH cursor1: page=%+v err=%v", pA1, errA1)

	// Case B: store visited via an empty query first.
	seen := NewStore()
	if _, err := seen.AuditQuery(org, 1, 10, "", ""); err != nil {
		t.Fatal(err)
	}
	pB0, errB0 := seen.AuditPage(cp, 0, 10, "", "")
	t.Logf("SEEN  cursor0: page=%+v err=%v", pB0, errB0)
	pB1, errB1 := seen.AuditPage(cp, 1, 10, "", "")
	t.Logf("SEEN  cursor1: page=%+v err=%v", pB1, errB1)

	// After saving empty checkpoint, records arrive; old checkpoint stays closed.
	seen.Decide(org, request(org, "u1", "r1", "org/a", "read"))
	pC1, errC1 := seen.AuditPage(cp, 1, 10, "", "")
	t.Logf("GROWN cursor1: page=%+v err=%v", pC1, errC1)
	pC2, errC2 := seen.AuditPage(cp, 2, 10, "", "")
	t.Logf("GROWN cursor2: page=%+v err=%v (want ErrInvalidRange)", pC2, errC2)
	if !errors.Is(errC2, ErrInvalidRange) {
		t.Fatalf("cursor2 err = %v", errC2)
	}

	// Foreign root fingerprint.
	foreign := cp
	foreign.Fingerprint = genesisFingerprint("other")
	if _, err := fresh.AuditPage(foreign, 1, 10, "", ""); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("foreign fp err = %v", err)
	}
}

